A set of options for placement options. Possible keys: "floor", "wall", "ceiling". You can specify different models for the different placements in the itemResource field. Example { "id": "mynamespace:small_gold_coin_piles", "itemFrame": true, "itemResource": { "models": { "default": "minecraft:item/diamond_sword", "wall": "minecraft:custom/hats/backpack", "ceiling": "minecraft:custom/furniture/misc/small_gold_coin_piles", "floor": "minecraft:custom/furniture/misc/small_gold_coin_piles" } }, "properties": { "rotate": true, "rotateSmooth": true, "placement": { "wall": true, "floor": true, "ceiling": true } }
} Default values: { "placement": { "floor": true, "wall": false, "ceiling": false }
}

